func Use(opener ResourceOpener, input string) (err error) {
	var resource Resource
	for {
		r, openErr := opener()
		if openErr == nil {
			resource = r
			break
		}
		if _, ok := openErr.(TransientError); ok {
			continue
		}
		return openErr
	}

	defer resource.Close()

	defer func() {
		if r := recover(); r != nil {
			if frobErr, ok := r.(FrobError); ok {
				resource.Defrob(frobErr.defrobTag)
				err = frobErr
				return
			}
			if e, ok := r.(error); ok {
				err = e
				return
			}
			panic(r)
		}
	}()

	resource.Frob(input)
	return nil
}
"}

